# -*- coding: utf-8 -*-
"""Generate the tool index Markdown from the manifest."""

import os
from pathlib import Path

from _toolchain_manifest import sorted_tools

TYPE_LABELS = {
    "page": "页件",
    "window": "窗口",
    "action": "动作",
    "hud": "运行内",
    "cli": "CLI",
    "gate": "门禁",
    "build": "构建",
    "content": "内容",
    "docs": "说明",
}

PLANE_LABELS = {
    "editor": "编辑器",
    "runtime": "运行时",
    "external": "游戏外",
    "none": "无执行",
}

PURPOSE_LABELS = {
    "debug": "调试",
    "dev": "开发",
    "delivery": "交付",
}

HEADER = (
    "<!-- AUTO-GENERATED by scripts/toolchain.py docs; DO NOT EDIT. "
    "Source: scripts/gate/toolchain.json -->\n"
    "# 工具索引\n\n"
    "> 生成命令：`python scripts/toolchain.py docs`。"
    "手工修改会在 `toolchain.py check` / `docs --check` 中报 stale。\n"
    "> 工具清单唯一来源：`scripts/gate/toolchain.json`。\n"
)


def _cell(value):
    return str(value).replace("|", "\\|").replace("\n", " ").strip()


def _relative_link(root, docs, doc_path):
    target = Path(root) / docs
    relative = os.path.relpath(str(target), str(Path(doc_path).parent)).replace(os.sep, "/")
    return f"[文档]({relative})"


def _entry(tool):
    kind = tool.get("kind")
    if kind == "hud":
        return "游戏内 F1（Hub 不执行）"
    if kind in {"page", "window", "action"}:
        return f"`python scripts/toolchain.py open {tool['id']}`"
    command = tool.get("command")
    if command:
        return "`" + " ".join(command) + "`"
    return "—"


def _writes(tool):
    scopes = ", ".join(tool.get("writes") or []) or "—"
    if tool.get("destructive"):
        return scopes + "（破坏性）"
    return scopes


def _safety(tool):
    safety = tool.get("safety") or {}
    outputs = tool.get("outputs") or []
    parts = []
    if safety.get("dryRun") == "supported":
        parts.append("预览")
    if safety.get("undo") == "file":
        parts.append("回滚")
    if outputs:
        parts.append(f"{len(outputs)} 产物")
    return " / ".join(parts) if parts else "—"


def render_docs(manifest, root, doc_path):
    lines = [HEADER]
    categories = sorted(manifest.get("categories", []), key=lambda item: item.get("order", 1000))
    for category in categories:
        tools = sorted_tools(manifest, category.get("id"))
        lines.append(f"## {category.get('title', category.get('id'))}\n")
        if not tools:
            lines.append("_暂无工具。_\n")
            continue
        lines.append("| ID | 工具 | 类型 | 平面 | 用途 | 入口 / 命令 | 写入面 | 安全 / 产物 | 文档 |")
        lines.append("|---|---|---|---|---|---|---|---|---|")
        for tool in tools:
            lines.append(
                "| {id} | {title} | {kind} | {plane} | {purpose} | {entry} | {writes} | {safety} | {docs} |".format(
                    id=_cell(tool["id"]),
                    title=_cell(tool["title"]),
                    kind=_cell(TYPE_LABELS.get(tool.get("kind"), tool.get("kind"))),
                    plane=_cell(PLANE_LABELS.get(tool.get("plane"), tool.get("plane"))),
                    purpose=_cell(PURPOSE_LABELS.get(tool.get("purpose"), tool.get("purpose"))),
                    entry=_entry(tool),
                    writes=_cell(_writes(tool)),
                    safety=_cell(_safety(tool)),
                    docs=_relative_link(root, tool["docs"], doc_path),
                )
            )
        lines.append("")

    lines.append("## 外部注册面\n")
    surfaces = manifest.get("surfaces", [])
    if not surfaces:
        lines.append("_未登记。_\n")
    else:
        lines.append("| ID | 类型 | 目标 | 必填 |")
        lines.append("|---|---|---|---|")
        for surface in surfaces:
            kind = surface.get("kind", "")
            if kind == "scheduled-task":
                target = "{name} → {script} ({runner})".format(
                    name=surface.get("name", ""),
                    script=surface.get("script", ""),
                    runner=surface.get("runner", ""),
                )
            else:
                target = surface.get("path", "")
            lines.append(
                "| {id} | {kind} | {target} | {required} |".format(
                    id=_cell(surface.get("id", "")),
                    kind=_cell(kind),
                    target=_cell(target),
                    required="是" if surface.get("required", True) else "否",
                )
            )
        lines.append("")
    return "\n".join(lines)


def write_docs(manifest, root, doc_path):
    content = render_docs(manifest, root, doc_path)
    data = content.encode("utf-8")
    doc_path = Path(doc_path)
    if doc_path.is_file() and doc_path.read_bytes() == data:
        return False
    doc_path.parent.mkdir(parents=True, exist_ok=True)
    with open(doc_path, "w", encoding="utf-8", newline="\n") as handle:
        handle.write(content)
    return True


def check_docs(manifest, root, doc_path):
    doc_path = Path(doc_path)
    if not doc_path.is_file():
        return False, f"generated index missing: {doc_path}"
    expected = render_docs(manifest, root, doc_path).encode("utf-8")
    if doc_path.read_bytes() != expected:
        return False, f"generated index is stale: {doc_path} (run: python scripts/toolchain.py docs)"
    return True, f"generated index current: {doc_path}"
